@Test
public void testMissingCommits() throws Exception {
    // Tests the behavior of SDP when commits that are given at ctor are missing
    // on onInit().
    Directory dir = newDirectory();
    IndexWriter writer = new IndexWriter(dir, getConfig(random(), getDeletionPolicy()));
    SnapshotDeletionPolicy sdp = (SnapshotDeletionPolicy) writer.getConfig().getIndexDeletionPolicy();
    writer.addDocument(new Document());
    writer.commit();
    IndexCommit s1 = sdp.snapshot();
    // create another commit, not snapshotted.
    writer.addDocument(new Document());
    writer.close();
    // open a new writer w/ KeepOnlyLastCommit policy, so it will delete "s1"
    // commit.
    new IndexWriter(dir, getConfig(random(), null)).close();
    assertFalse("snapshotted commit should not exist", slowFileExists(dir, s1.getSegmentsFileName()));
    dir.close();
}

@Test
public void testPad() {
    int[] tests = new int[] { -9999999, -99560, -100, -3, -1, 0, 3, 9, 10, 1000, 999999999 };
    for (int i = 0; i < tests.length - 1; i++) {
        int a = tests[i];
        int b = tests[i + 1];
        String aa = pad(a);
        String bb = pad(b);
        String label = a + ":" + aa + " vs " + b + ":" + bb;
        assertEquals("length of " + label, aa.length(), bb.length());
        assertTrue("compare less than " + label, aa.compareTo(bb) < 0);
    }
}

