@Test
public void testRandomQueries() throws Exception {
    String[] vals = { "w1", "w2", "w3", "w4", "w5", "xx", "yy", "zzz" };
    BooleanQuery q1 = null;
    try {
        // increase number of iterations for more complete testing
        int num = atLeast(3);
        for (int i = 0; i < num; i++) {
            int level = random().nextInt(3);
            q1 = randBoolQuery(new Random(random().nextLong()), random().nextBoolean(), level, field, vals, null).build();
            // Can't sort by relevance since floating point numbers may not quite
            // match up.
            Sort sort = Sort.INDEXORDER;
            // baseline sim
            QueryUtils.check(random(), q1, searcher);
            try {
                // a little hackish, QueryUtils.check is too costly to do on bigSearcher in this loop.
                // random sim
                searcher.setSimilarity(bigSearcher.getSimilarity());
                QueryUtils.check(random(), q1, searcher);
            } finally {
                // restore
                searcher.setSimilarity(new ClassicSimilarity());
            }
            // check diff (randomized) scorers (from AssertingSearcher) produce the same results
            ScoreDoc[] hits1 = searcher.search(q1, TopFieldCollector.createSharedManager(sort, 1000, null, 1)).scoreDocs;
            TopDocs topDocs = searcher.search(q1, TopFieldCollector.createSharedManager(sort, 1000, null, 1));
            ScoreDoc[] hits2 = topDocs.scoreDocs;
            CheckHits.checkEqual(q1, hits1, hits2);
            BooleanQuery.Builder q3 = new BooleanQuery.Builder();
            q3.add(q1, BooleanClause.Occur.SHOULD);
            q3.add(new PrefixQuery(new Term("field2", "b")), BooleanClause.Occur.SHOULD);
            assertEquals(mulFactor * topDocs.totalHits.value + NUM_EXTRA_DOCS / 2, bigSearcher.count(q3.build()));
            // test diff (randomized) scorers produce the same results on bigSearcher as well
            hits1 = bigSearcher.search(q1, TopFieldCollector.createSharedManager(sort, 1000 * mulFactor, null, 1)).scoreDocs;
            hits2 = bigSearcher.search(q1, TopFieldCollector.createSharedManager(sort, 1000 * mulFactor, null, 1)).scoreDocs;
            CheckHits.checkEqual(q1, hits1, hits2);
        }
    } catch (Exception e) {
        // For easier debugging
        System.out.println("failed query: " + q1);
        throw e;
    }
    // System.out.println("Total hits:"+tot);
}

