            ts = new PorterStemFilter(ts);
            return new TokenStreamComponents(tokenizer, ts);
        }
    };
    new IndexBuilder(this::toField).doc(FLD_TEXT1, "Where the moon shine falls, firewater flows.").build(analyzer, reader -> {
