ps over the lazy dog" }, { "fn:atLeast(2 fn:unordered(furry dog) fn:unordered(brown dog) lazy quick)", "0. %s: The >quick >brown fox jumps over the lazy<<> dog<" }, { "fn:extend(fox 1 2)", "0. %s: The quick >brown fox jumps over< the lazy dog" }, { "fn:extend(fn:or(dog fox) 2 0)", "0. %s: The >quick brown fox< jumps over >the lazy dog<" }, { "fn:containedBy(fn:or(fox dog) fn:extend(lazy 3 3))", "0. %s: The quick brown fox jumps over the lazy >dog<" }, { "fn:notContainedBy(fn:or(fox dog) fn:extend(lazy 3 3))", "0. %s: The quick brown >fox< jumps over the lazy dog" }, { "fn:containing(fn:extend(fn:or(lazy brown) 1 1) fn:or(fox dog))", "0. %s: The >quick brown fox< jumps over >the lazy dog<" }, { "fn:notContaining(fn:extend(fn:or(fox dog) 1 0) fn:or(brown yellow))", "0. %s: The quick brown fox jumps over the >lazy dog<" } });
        // Verify assertions.
        new IndexBuilder(this::toField).// Just one document and multiple interval queries to check.
        doc(field, inputDocument).build(analyzer, reader -> {
            IndexSearcher searcher = new IndexSearcher(reader);
            // So that results are consistently ordered.
            Sort sortOrder = Sort.INDEXORDER;
            MatchHighlighter highlighter = new MatchHighlighter(searcher, analyzer).appendFieldHighlighter(FieldValueHighlighters.highlighted(80 * 3, 1, new PassageFormatter("...", ">", "<"), fld -> true)).appendFieldHighlighter(FieldValueHighlighters.skipRemaining());
            StandardQueryParser qp = new StandardQueryParser(analyzer);
            // Run all pairs of query-expected highlight.
            List<String> errors = new ArrayList<>();
            for (var queryHighlightPair : queryResultPairs) {
                assert queryHighlightPair.length >= 1;
                String queryString = queryHighlightPair[0];
                var query = qp.parse(queryString, field);
                var expected = Arrays.stream(queryHighlightPair).skip(1).map(v -> String.format(Locale.ROOT, v, field)).toArray(String[]::new);
                try {
                    assertHighlights(toDocList(highlighter.highlight(searcher.search(query, 10, sortOrder), query)), expected);
                } catch (AssertionError e) {
                    errors.add("MISMATCH: query: " + queryString + "\n" + e.getMessage());
                }
            }
            if (errors.size() > 0) {
                throw new AssertionError(String.join("\n\n", errors));
            }
        });
    }
}

@Test
public void testCustomFieldHighlightHandling() throws Exception {
    // Match highlighter is a showcase of individual components in this package, suitable
    // to create any kind of field-display designs.
    //
    // In this example we will build a custom field highlighting handler that
    // highlights matches over a multivalued field, shows that field's values if it received
    // no matches and limits the number of values displayed to at most 2 (with an appropriate
    // message).
    new IndexBuilder(this::toField).// Just one document, one field, four values.
    doc(FLD_TEXT1, "foo bar", "bar foo baz", "bar baz foo", "baz baz baz").build(analyzer, reader -> {
        IndexSearcher searcher = new IndexSearcher(reader);
        Sort sortOrder = Sort.INDEXORDER;
        // Let's start with the simple predefined highlighter so that the field's value shows
        // and is highlighted when it was part of the hit.
        MatchHighlighter.FieldValueHighlighter highlighted = FieldValueHighlighters.highlighted(80 * 3, 2, new PassageFormatter("...", ">", "<"), FLD_TEXT1::equals);
        MatchHighlighter highlighter = new MatchHighlighter(searcher, analyzer).appendFieldHighlighter(highlighted).appendFieldHighlighter(FieldValueHighlighters.skipRemaining());
        Query query = new TermQuery(new Term(FLD_TEXT1, "foo"));
        TopDocs topDocs = searcher.search(query, 10, sortOrder);
        // Note the highlighter is configured with at most 2 snippets so the match on the
        // third value ("bar baz foo") is omitted. Ellipsis isn't inserted too because
        // values are displayed in full.
        assertHighlights(toDocList(highlighter.highlight(topDocs, query)), "0. text1: >foo< bar, bar >foo< baz");
        // So the above works fine if the field received a match but omits it otherwise. We
        // can
        // force the display of this field by chaining with verbatim value highlighter:
        highlighter = new MatchHighlighter(searcher, analyzer).appendFieldHighlighter(highlighted.or(FieldValueHighlighters.verbatimValue(FLD_TEXT1))).appendFieldHighlighter(FieldValueHighlighters.skipRemaining());
        assertHighlights(toDocList(highlighter.highlight(topDocs, new MatchAllDocsQuery())), "0. text1: foo bar, bar foo baz, bar baz foo, baz baz baz");
        // But this is not exactly what we'd like because we want to limit the display of
        // values to the first two.
        // Let's just write a custom field highlighter handler that does it.
        class AtMostNValuesHighlighter implements MatchHighlighter.FieldValueHighlighter {

            private final String field;

            private final int limit;

            AtMostNValuesHighlighter(String field, int limit) {
                this.field = field;
                this.limit = limit;
            }

            @Override
            public boolean isApplicable(String field, boolean hasMatches) {
                return Objects.equals(field, this.field);
            }

            @Override
            public List<String> format(String field, String[] values, String contiguousValue, List<OffsetRange> valueRanges, List<MatchHighlighter.QueryOffsetRange> matchOffsets) {
                if (values.length <= limit) {
                    return Arrays.asList(values);
                } else {
                    List<String> collected = Stream.of(values).limit(limit).collect(Collectors.toList());
                    int remaining = values.length - collected.size();
                    collected.add(String.format(Locale.ROOT, "[%d omitted]", remaining));
                    return collected;
                }
            }

            @Override
            public Collection<String> alwaysFetchedFields() {
                return Collections.singleton(field);
            }
        }
        // We can now chain it as usual and contemplate the result.
        highlighter = new MatchHighlighter(searcher, analyzer).appendFieldHighlighter(highlighted.or(new AtMostNValuesHighlighter(FLD_TEXT1, 2))).appendFieldHighlighter(FieldValueHighlighters.skipRemaining());
        assertHighlights(toDocList(highlighter.highlight(topDocs, query)), "0. text1: >foo< bar, bar >foo< baz");
        assertHighlights(toDocList(highlighter.highlight(topDocs, new MatchAllDocsQuery())), "0. text1: foo bar, bar foo baz, [2 omitted]");
    });
}

@Test
public void testHighlightMoreQueriesAtOnceShowoff() throws Exception {
    // Match highlighter underlying components are powerful enough to build interesting,
    // if not always super-practical, things. In this case, we would like to highlight
    // a set of matches of *more than one* query over the same set of input documents. This includes
    // highest-scoring passage resolution (from multiple hits) and different highlight markers
    // for each query.
    new IndexBuilder(this::toField).doc(FLD_TEXT1, "foo bar baz").doc(FLD_TEXT1, "foo baz bar").build(analyzer, reader -> {
        // Let's start with the two queries. The first one will be an unordered
        // query for (foo, baz) with a max gap of 1; let's use intervals for this.
        Query q1 = new IntervalQuery(FLD_TEXT1, Intervals.maxgaps(1, Intervals.unordered(Intervals.term("foo"), Intervals.term("baz"))));
        // The second one will be a simpler term query for "bar".
        Query q2 = new TermQuery(new Term(FLD_TEXT1, "bar"));
        // Let's fetch matching documents by combining the two into a Boolean query.
        Query query = new BooleanQuery.Builder().add(q1, BooleanClause.Occur.SHOULD).add(q2, BooleanClause.Occur.SHOULD).build();
        IndexSearcher searcher = new IndexSearcher(reader);
        // So that results are consistently ordered.
        Sort sortOrder = Sort.INDEXORDER;
        TopDocs topDocs = searcher.search(query, 10, sortOrder);
        // If we use the "regular" highlighter, the result will be slightly odd: a nested
        // highlight over "bar" within the first match. Also, you can't distinguish which of
        // the sub-queries
        // caused which highlight marker... but if it were HTML then you could give the span
        // some semi-translucent background and layered matches would be visible.
        MatchHighlighter highlighter = new MatchHighlighter(searcher, analyzer).appendFieldHighlighter(FieldValueHighlighters.highlighted(80 * 3, 1, new PassageFormatter("...", "<span>", "</span>"), FLD_TEXT1::equals)).appendFieldHighlighter(FieldValueHighlighters.skipRemaining());
        assertHighlights(toDocList(highlighter.highlight(topDocs, query)), "0. text1: <span>foo <span>bar</span> baz</span>", "1. text1: <span>foo baz</span> <span>bar</span>");
        // To separate highlights for multiple queries we'll pass them separately to the
        // highlighter and differentiate highlight markers upon their application. Let's start
        // with the customized
        // field highlighter first. This utilizes the fact that match ranges passed from
        // MatchHighlighter
        // contain a reference to the original query which brought up the match.
        class SeparateMarkerFieldHighlighter implements MatchHighlighter.FieldValueHighlighter {

            private final String field;

            private final Map<Query, String> queryClassMap;

            SeparateMarkerFieldHighlighter(String field, Map<Query, String> queryClassMap) {
                this.field = field;
                this.queryClassMap = queryClassMap;
            }

            @Override
            public boolean isApplicable(String field, boolean hasMatches) {
                return Objects.equals(field, this.field) && hasMatches;
            }

            @Override
            public List<String> format(String field, String[] values, String contiguousValue, List<OffsetRange> valueRanges, List<MatchHighlighter.QueryOffsetRange> matchOffsets) {
                PassageSelector passageSelector = new PassageSelector();
                int maxPassageWindow = 80;
                int maxPassages = 3;
                List<Passage> bestPassages = passageSelector.pickBest(contiguousValue, matchOffsets, maxPassageWindow, maxPassages, valueRanges);
                // We know the offset ranges passed to us by MatchHighlighter are instances of
                // QueryOffsetRange
                // so we compute the class based on that.
                Function<OffsetRange, String> queryToClass = (range) -> queryClassMap.get(((MatchHighlighter.QueryOffsetRange) range).query);
                PassageFormatter passageFormatter = new PassageFormatter("...", (range) -> "<span class='" + queryToClass.apply(range) + "'>", (range) -> "</span>");
                return passageFormatter.format(contiguousValue, bestPassages, valueRanges);
            }
        }
        // And this is pretty much it. We now set up query classes to display, set up the
        // highlighter...
        Map<Query, String> queryClassMap = Map.of(q1, "q1", q2, "q2");
        highlighter = new MatchHighlighter(searcher, analyzer).appendFieldHighlighter(new SeparateMarkerFieldHighlighter(FLD_TEXT1, queryClassMap)).appendFieldHighlighter(FieldValueHighlighters.skipRemaining());
        // ...and run highlighting. Note the query passed to the highlighter are individual
        // sub-clauses
        // of the Boolean query used to fetch documents.
        assertHighlights(toDocList(highlighter.highlight(topDocs, q1, q2)), "0. text1: <span class='q1'>foo <span class='q2'>bar</span> baz</span>", "1. text1: <span class='q1'>foo baz</span> <span class='q2'>bar</span>");
    });
}

