public void testNoRewrite() throws Exception {
    String field1 = FLD_TEXT_POS_OFFS1;
    String field2 = FLD_TEXT_POS_OFFS2;
    new IndexBuilder(this::toField).doc(fields -> {
        fields.add(field1, "0100");
