    }).doc(fields -> {
        fields.add(field1, "0200");
        fields.add(field2, "foo bar");
    }).build(analyzer, reader -> {
        String expected = fmt("0: (%s: '>0100<')(%s: 'loo >bar<')", field1, field2);
        MatcherAssert.assertThat(highlights(reader, stdQueryParser.apply(fmt("+%s:01* OR %s:bar", field1, field2), field1)), containsInAnyOrder(expected));
        MatcherAssert.assertThat(highlights(reader, stdQueryParser.apply(fmt("+%s:01* AND %s:bar", field1, field2), field1)), containsInAnyOrder(expected));
    });
}

