/**
 * This test runs a term query against a field with no stored positions or offsets. This test
 * checks the {@link OffsetsFromValues} strategy that returns highlights over entire indexed
 * values.
 */
@Test
public void testTextFieldNoPositionsOffsetFromValues() throws Exception {
    String field = FLD_TEXT_NOPOS;
    new IndexBuilder(this::toField).doc(FLD_TEXT_NOPOS, "foo bar").doc(FLD_TEXT_NOPOS, "foo bar", "baz baz").build(analyzer, reader -> {
        OffsetsRetrievalStrategySupplier defaults = MatchRegionRetriever.computeOffsetRetrievalStrategies(reader, analyzer);
        OffsetsRetrievalStrategySupplier customSuppliers = (fld) -> {
            if (fld.equals(field)) {
                return new OffsetsFromValues(field, analyzer);
            } else {
                return defaults.apply(field);
            }
        };
        MatcherAssert.assertThat(highlights(customSuppliers, reader, new TermQuery(new Term(field, "bar"))), containsInAnyOrder(fmt("0: (%s: '>foo bar<')", field), fmt("1: (%s: '>foo bar< | >baz baz<')", field)));
    });
}

