@Test
public void testIntersections() throws Exception {
    setupDocs();
    // Try some edge cases
    // NOTE: 2nd arg is distance in kilometers
    checkHitsCircle(shapeFactory.pointXY(1, 1), 175, 3, 5, 6, 7);
    checkHitsCircle(shapeFactory.pointXY(179.8, 0), 200, 2, 8, 9);
    checkHitsCircle(shapeFactory.pointXY(50, 89.8), 200, 2, 10, // this goes over the north pole
    11);
    checkHitsCircle(shapeFactory.pointXY(50, -89.8), 200, 2, 12, // this goes over the south pole
    13);
    // try some normal cases
    checkHitsCircle(shapeFactory.pointXY(-80.0, 33.0), 300, 2);
    // large distance
    checkHitsCircle(shapeFactory.pointXY(1, 1), 5000, 3, 5, 6, 7);
    // Because we are generating a box based on the west/east longitudes and the south/north
    // latitudes, which then
    // translates to a range query, which is slightly more inclusive.  Thus, even though 0.0 is
    // 15.725 kms away,
    // it will be included, b/zScaling of the box calculation.
    checkHitsBBox(shapeFactory.pointXY(0.1, 0.1), 15, 2, 5, 6);
    // try some more
    deleteAll();
    adoc("14", shapeFactory.pointXY(5, 0));
    adoc("15", shapeFactory.pointXY(15, 0));
    // 3000KM from 0,0, see http://www.movable-type.co.uk/scripts/latlong.html
    adoc("16", shapeFactory.pointXY(19.79750, 18.71111));
    adoc("17", shapeFactory.pointXY(-95.436643, 44.043900));
    commit();
    checkHitsCircle(shapeFactory.pointXY(0, 0), 1000, 1, 14);
    checkHitsCircle(shapeFactory.pointXY(0, 0), 2000, 2, 14, 15);
    checkHitsBBox(shapeFactory.pointXY(0, 0), 3000, 3, 14, 15, 16);
    checkHitsCircle(shapeFactory.pointXY(0, 0), 3001, 3, 14, 15, 16);
    checkHitsCircle(shapeFactory.pointXY(0, 0), 3000.1, 3, 14, 15, 16);
    // really fine grained distance and reflects some of the vagaries of how we are calculating the
    // box
    checkHitsCircle(shapeFactory.pointXY(-96.789603, 43.517030), 109, 0);
    // falls outside of the real distance, but inside the bounding box
    checkHitsCircle(shapeFactory.pointXY(-96.789603, 43.517030), 110, 0);
    checkHitsBBox(shapeFactory.pointXY(-96.789603, 43.517030), 110, 1, 17);
}

@Test
public void testEqualsHashCode() {
    switch(// 0-3
    random().nextInt(4)) {
        case 0:
            predicate = SpatialOperation.Contains;
            break;
        case 1:
            predicate = SpatialOperation.IsWithin;
            break;
        default:
            predicate = SpatialOperation.Intersects;
            break;
    }
    final SpatialPrefixTree gridQuad = new QuadPrefixTree(ctx, 10);
    final SpatialPrefixTree gridGeohash = new GeohashPrefixTree(ctx, 10);
    Collection<SpatialStrategy> strategies = new ArrayList<>();
    RecursivePrefixTreeStrategy recursive_geohash = new RecursivePrefixTreeStrategy(gridGeohash, "recursive_geohash");
    strategies.add(recursive_geohash);
    strategies.add(new TermQueryPrefixTreeStrategy(gridQuad, "termquery_quad"));
    strategies.add(PointVectorStrategy.newInstance(ctx, "pointvector"));
    strategies.add(BBoxStrategy.newInstance(ctx, "bbox"));
    final SerializedDVStrategy serialized = new SerializedDVStrategy(ctx, "serialized");
    strategies.add(serialized);
    strategies.add(new CompositeSpatialStrategy("composite", recursive_geohash, serialized));
    for (SpatialStrategy strategy : strategies) {
        testEqualsHashcode(strategy);
    }
}

@Test
public void calcDistanceFromErrPct() {
    final SpatialContext ctx = usually() ? SpatialContext.GEO : new Geo3dSpatialContextFactory().newSpatialContext();
    // distErrPct
    final double DEP = 0.5;
    // the result is the diagonal distance from the center to the closest corner,
    // times distErrPct
    Shape superwide = ctx.makeRectangle(-180, 180, 0, 0);
    // 0 distErrPct means 0 distance always
    assertEquals(0, SpatialArgs.calcDistanceFromErrPct(superwide, 0, ctx), 0);
    assertEquals(180 * DEP, SpatialArgs.calcDistanceFromErrPct(superwide, DEP, ctx), 0);
    Shape supertall = ctx.makeRectangle(0, 0, -90, 90);
    assertEquals(90 * DEP, SpatialArgs.calcDistanceFromErrPct(supertall, DEP, ctx), 0);
    Shape upperhalf = ctx.makeRectangle(-180, 180, 0, 90);
    assertEquals(45 * DEP, SpatialArgs.calcDistanceFromErrPct(upperhalf, DEP, ctx), 0.0001);
    Shape midCircle = ctx.makeCircle(0, 0, 45);
    assertEquals(60 * DEP, SpatialArgs.calcDistanceFromErrPct(midCircle, DEP, ctx), 0.0001);
}

